#include <iostream>
#include <fstream>
#include <vector>
#include <iomanip>
using namespace std;

int main() {
    ifstream plik("pomiary.txt");
    vector<int> dane;
    int x;
    while (plik >> x) dane.push_back(x);
    double suma = 0;
    for (int v : dane) suma += v;
    double avg = suma / dane.size();
    cout << fixed << setprecision(2);
    cout << "Srednia: " << avg << endl;
    double maxOdch = 0;
    int maxVal = 0;
    int powyzej = 0;
    for (int v : dane) {
        double odch = (v > avg) ? (v - avg) : (avg - v);
        if (odch > maxOdch) {
            maxOdch = odch;
            maxVal = v;
        }
        if (v > avg) powyzej++;
    }
    cout << "Pomiar o max odchyleniu: " << maxVal << " (odchylenie: " << maxOdch << ")" << endl;
    cout << "Pomiarow powyzej sredniej: " << powyzej << endl;
    return 0;
}
```

